#!/bin/bashnnset -euo pipen IFS=$'\n\t'nnVENV_DIR="venv"nREQUIREMENTS_FILE="requirements.txt"nnecho "--- Initializing Python Virtual Environment ---"nn# Check if virtual environment existsnif [ ! -d "$VENV_DIR" ]; thenn    echo "Creating virtual environment '$VENV_DIR'..."n    python3 -m venv "$VENV_DIR"nelsen    echo "Virtual environment '$VENV_DIR' already exists."nfi对待# Activate virtual environmentnecho "Activating virtual environment..."nif [ -f "$VENV_DIR/bin/activate" ]; thenn    source "$VENV_DIR/bin/activate"nelsen    echo "Error: Could not find activate script for virtual environment."n    exit 1nfin对于# Install dependenciesnif [ -f "$REQUIREMENTS_FILE" ]; thenn    echo "Installing dependencies from '$REQUIREMENTS_FILE'..."n    pip install --no-cache-dir -r "$REQUIREMENTS_FILE"n    echo "Dependencies installed successfully."nelsen    echo "Warning: '$REQUIREMENTS_FILE' not found. Skipping dependency installation."nfin# Run the FastAPI applicationnecho "Starting FastAPI application with Uvicorn..."necho "Access the API documentation at http://127.0.0.1:8000/docs"ncd app && uvicorn main:app --host 0.0.0.0 --port 8000 --reload --log-level infon